        dp[j] = 1LL * inf * inf;
        for ( int x = j; x != 1; x /= isPrime[x] )
            dp[j] = min( dp[j], 1LL * dp[j / isPrime[x]] + 1LL * j * ( isPrime[x] - 1 ) / 2LL );
